import {t,getLanguage,setLanguage,fold} from './i18n.js';
import {createCloudClient,createShareClient,readShareToken} from './cloud.js';
import cloudConfig from './config.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',book:'M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3V3Zm4 0v18M12 8h4M12 12h4',pill:'m9 15 6-6M5 19a5 5 0 0 1 0-7l7-7a5 5 0 0 1 7 7l-7 7a5 5 0 0 1-7 0Z',image:'M3 4h18v16H3V4Zm0 12 6-6 5 5 3-3 4 4M15 8h.01',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',left:'M19 12H5m5-5-5 5 5 5',check:'m5 12 4 4L19 6',calendar:'M4 5h16v16H4V5ZM8 3v4m8-4v4M4 10h16',folder:'M3 6h7l2 3h9v11H3V6Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 17V5m-5 5 5-5 5 5M4 16v5h16v-5',refresh:'M20 10a8 8 0 0 0-14-5L3 8m0-5v5h5M4 14a8 8 0 0 0 14 5l3-3m0 5v-5h-5',close:'m6 6 12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4v-4Zm10-10 4 4',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',logout:'M9 4H4v16h5m6-12 4 4-4 4M8 12h12',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',copy:'M8 8h12v13H8V8ZM16 8V3H3v13h5',mask:'M4 4h16v16H4V4Zm3 3 10 10M7 12l5 5m0-10 5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const uuid=()=>crypto.randomUUID();
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayDiff=d=>Math.round((Date.parse(d+'T12:00:00Z')-Date.parse(today()+'T12:00:00Z'))/86400000);
const alias=id=>t(id==='grandpa'?'grandpa':'grandma');
const dateText=d=>d?String(d).replaceAll('-',' / '):t('dateMissing');
const sourceIds=v=>[...new Set([...(v.source_file_ids||[]),...(v.medicines||[]).flatMap(m=>m.source_file_ids||[])])];
const badge=(s,type='')=>`<span class="badge ${type}">${esc(s)}</span>`;
const statusBadge=v=>badge(t(v.status==='confirmed'?'confirmed':'draft'),v.status==='confirmed'?'':'pending');
const avatar=id=>`<span class="avatar ${id==='grandma'?'grandma':''}" aria-hidden="true">${id==='grandpa'?(getLanguage()==='zh-Hans'?'爷':'爺'):'嬷'}</span>`;
const localHost=['127.0.0.1','localhost','[::1]'].includes(location.hostname);
const state={view:localHost&&new URLSearchParams(location.search).get('view')!=='family'?'manage':'family',mode:'loading',route:'overview',person:null,category:'all',q:'',from:'',to:'',status:'all',data:{patients:[],visits:[],reports:[],attachments:[]},boot:null,client:null,session:null,share:null,shareAccess:false,detail:null,editor:null,detailKind:'visit',editorKind:'visit',storage:null,error:null,busy:false,demo:new URLSearchParams(location.search).get('demo')==='1',urls:new Map()};
let toastTimer;let redaction=null;let dataEpoch=0;let dialogEpoch=0;let actionInFlight=false;let initEpoch=0;
function toast(message,error=false){const e=$('#toast');e.textContent=message;e.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{e.className='';},6000);}
async function api(path,body){const opts={credentials:'same-origin',cache:'no-store',headers:state.boot?.csrf_token?{'X-CSRF-Token':state.boot.csrf_token}:{}};if(body!==undefined){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':state.boot?.csrf_token||''};opts.body=JSON.stringify(body);}const res=await fetch('/api'+path,opts);let data;try{data=await res.json();}catch{throw Error(t('reloadWarning'));}if(!res.ok)throw Error(data.error||`${t('failed')} (${res.status})`);return data;}
async function loadData(){
 const epoch=++dataEpoch,mode=state.mode,demo=state.demo,client=state.client;
 clearUrls();
 const data=demo?sampleData():mode==='local'?await api(state.view==='family'?'/family-data':'/data'):await client.getData();
 if(epoch!==dataEpoch||mode!==state.mode||demo!==state.demo||client!==state.client)return false;
 state.data=data;state.error=null;return true;
}
function clearSharedView(){
 ++dataEpoch;clearUrls();state.data={patients:[],visits:[],reports:[],attachments:[]};state.person=null;state.detail=null;state.editor=null;state.mode='share-denied';state.error=t('shareUnavailable');++dialogEpoch;redaction=null;$('#dialog')?.close();render();
}
function clearPrivateView(){
 ++dataEpoch;clearUrls();state.data={patients:[],visits:[],reports:[],attachments:[]};
 state.session=null;state.person=null;state.mode='login';state.detail=null;state.editor=null;state.error=null;
 ++dialogEpoch;redaction=null;$('#dialog')?.close();render();
}
const canOperate=()=>state.mode==='local'&&state.view==='manage';
const isLocal=()=>canOperate()&&!state.demo;
function filteredVisits(){return [...state.data.visits].filter(v=>v.patient_id===state.person&&(state.status==='all'||v.status===state.status)&&(!state.from||(v.date&&v.date>=state.from))&&(!state.to||(v.date&&v.date<=state.to))&&(!state.q||fold([alias(v.patient_id),v.date,v.doctor,v.clinic,v.reason,v.diagnosis,v.notes,...(v.medicines||[]).map(m=>[m.name,m.strength,m.instructions].join(' '))].join(' ')).includes(fold(state.q)))).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.updated_at||'').localeCompare(a.updated_at||''));}
function patientMeta(id){const p=state.data.patients.find(p=>p.id===id);return p?[p.age!=null?`${p.age} ${getLanguage()==='zh-Hans'?'岁':'歲'}`:'',p.sex&&p.sex!=='unknown'?t(p.sex):''].filter(Boolean).join(' · '):'';}
const btn=(label,action,ic='',type='',attrs='')=>`<button type="button" class="btn ${type}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${esc(label)}</button>`;
function chapterNumber(id){return id==='grandpa'?'01':'02';}
function brand(){return `<div class="brand"><img src="./icon.svg" alt=""><div><strong>${t('app')}</strong><small>${t('subtitle')}</small></div></div>`;}
function languageTools(){return `<div class="topbar-right"><span class="version-label">${t(canOperate()?'operatorVersion':'familyVersion')}</span>${canOperate()?`<a class="btn ghost small" href="?view=family" target="_blank" rel="noopener">${t('previewFamily')}</a>`:''}<button class="language" data-action="language">繁體 / 简体</button>${state.mode==='cloud'?btn(t('logout'),'logout','logout','ghost small'):''}</div>`;}
function demoBanner(){if(state.mode==='local'&&state.view==='family'&&!state.demo)return `<div class="preview-bar"><span>${t('familyPreviewNotice')}</span><a href="?view=manage">${t('returnManage')}</a></div>`;return state.demo?`<div class="demo-bar"><span>${t('demo')}</span><button data-action="exit-demo">${t('exitDemo')}</button></div>`:'';}
function chapterHome(){return `<main class="chapter-home"><header class="home-top">${brand()}${languageTools()}</header>${demoBanner()}<div class="home-heading"><span class="eyebrow">${t('chapters')}</span><h1>${t('chooseChapter')}</h1><p>${t(canOperate()?'operatorIntro':'chapterIntro')}</p></div><div class="chapter-covers">${['grandpa','grandma'].map(id=>{const visits=state.data.visits.filter(v=>v.patient_id===id).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<button class="chapter-cover ${id}" data-action="chapter" data-id="${id}"><span class="cover-number">${chapterNumber(id)}</span><span class="cover-body"><strong>${alias(id)}</strong><span class="cover-meta">${esc(patientMeta(id))||t('personalChapter')}</span><span class="cover-rule"></span><span class="cover-count">${visits.length} ${t('records')}</span><span class="cover-date">${visits[0]?.date?`${t('latestVisit')} · ${esc(dateText(visits[0].date))}`:t('chapterEmpty')}</span><span class="cover-enter">${t('enterChapter')}${icon('arrow')}</span></span></button>`;}).join('')}</div><footer class="home-footer"><span>${icon('shield')}${t('privacyFoot')}</span><span>${t(canOperate()?'local':'readOnly')}</span></footer></main>`;}
function shell(){return `<div class="shell"><aside class="sidebar">${brand()}<button class="chapter-return" data-action="chapters">${icon('left')}${t('chapterHome')}</button><div class="sidebar-label">${t('chapters')}</div><nav class="chapter-nav" aria-label="${t('chapters')}">${['grandpa','grandma'].map(id=>`<button class="chapter-nav-item ${id} ${state.person===id?'active':''}" data-action="chapter" data-id="${id}" ${state.person===id?'aria-current="page"':''}><span class="nav-number">${chapterNumber(id)}</span><span><strong>${alias(id)}</strong><small>${esc(patientMeta(id))||t('personalChapter')}</small></span></button>`).join('')}</nav><div id="medicine-categories" class="sidebar-categories">${state.route==='medicines'?categoryNav():''}</div><div class="side-bottom">${canOperate()?btn(t('settings'),'nav','settings','ghost','data-route="settings"'):''}<div class="mode">${t(canOperate()?'local':'readOnly')}</div></div></aside><main class="main"><div class="topbar"><button class="mobile-home" data-action="chapters">${icon('left')}${t('chapterHome')}</button><span class="desktop-crumb">${t('subtitle')} / ${alias(state.person)}</span>${languageTools()}</div>${demoBanner()}<div id="workspace"></div><footer class="footer-note"><span>${t('privacyFoot')}</span><span>${t('lastSync')} · ${esc(formatStamp(state.data.published_at||state.boot?.last_sync))}</span></footer></main></div>`;}
function formatStamp(s){if(!s)return t('never');const str=typeof s==='object'?(s.created_at||s.published_at||s.at||s.name):s;const d=new Date(str);return Number.isNaN(d.getTime())?String(str):new Intl.DateTimeFormat(getLanguage(),{timeZone:'Asia/Hong_Kong',dateStyle:'short',timeStyle:'short'}).format(d);}
function render(){document.documentElement.lang=getLanguage();document.title=`${t('app')} · ${t(canOperate()?'operatorVersion':'familyVersion')}`;if(state.mode==='loading')return;if(state.mode==='login'||state.mode==='setup'||state.mode==='denied'||state.mode==='share-denied')return renderAuth();if(state.error){$('#app').innerHTML=`<div class="initial"><img src="./icon.svg" width="48" height="48" alt=""><h1>${t('app')}</h1><div class="error-box"><h2>${t('failed')}</h2><p>${esc(state.error)}</p>${btn(t('retry'),'reload','refresh')}</div></div>`;return;}if(!['grandpa','grandma'].includes(state.person)){$('#app').innerHTML=chapterHome();return;}$('#app').innerHTML=shell();renderWorkspace();}
function renderWorkspace(){if(!canOperate()&&!['visits','medicines','reports'].includes(state.route))state.route='visits';const el=$('#workspace');if(!el)return;if(state.editor){el.innerHTML=state.editorKind==='report'?renderReportEditor():renderEditor();return;}if(state.detail){el.innerHTML=state.detailKind==='report'?renderReportDetail():renderDetail();loadThumbnails();return;}el.innerHTML=heading()+chapterTabs()+(['overview','visits','medicines','reports'].includes(state.route)?searchBar():'')+'<div id="page-body"></div>';renderBody();}
function heading(){return `<header class="page-heading"><div><h1><span class="heading-number">${chapterNumber(state.person)}</span><span class="heading-slash">/</span>${alias(state.person)}</h1><p>${esc(patientMeta(state.person))||t('personalChapter')}</p></div><div class="actions">${canOperate()&&['overview','visits'].includes(state.route)?btn(t('newVisit'),'new','plus','primary'):''}${canOperate()&&state.route==='reports'?btn(t('newReport'),'new-report','plus','primary'):''}${['cloud','share'].includes(state.mode)?btn(t('refresh'),'reload','refresh'):''}</div></header>`;}
function chapterTabs(){const routes=canOperate()?['overview','visits','medicines','reports','files','settings']:['visits','medicines','reports'];return `<nav class="chapter-tabs" aria-label="${alias(state.person)} ${t('chapters')}">${routes.map(r=>`<button data-action="nav" data-route="${r}" class="${state.route===r?'active':''}" ${state.route===r?'aria-current="page"':''}>${t(r)}</button>`).join('')}</nav>`;}
function searchBar(){return `<div class="search-row"><label class="search">${icon('search')}<input id="search" type="search" value="${esc(state.q)}" placeholder="${t('search')}" aria-label="${t('search')}" autocomplete="off"></label>${['visits','reports'].includes(state.route)?`<div class="date-filters"><label for="from">${t('from')}</label><input class="filter-control" type="date" id="from" value="${state.from}"><label for="to">${t('to')}</label><input class="filter-control" type="date" id="to" value="${state.to}"></div>`:''}${canOperate()?`<select class="filter-control" id="status-filter" aria-label="${t('status')}">${[['all','allStatuses'],['confirmed','confirmed'],['draft','draft']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${t(l)}</option>`).join('')}</select>`:''}</div>`;}
function renderBody(){const categories=$('#medicine-categories');if(categories)categories.innerHTML=state.route==='medicines'?categoryNav():'';const body=$('#page-body');if(!body)return;body.innerHTML=state.route==='overview'?overview():state.route==='visits'?visitList(filteredVisits()):state.route==='medicines'?medicineList():state.route==='reports'?reportList():state.route==='files'?filesPage():settingsPage();loadThumbnails();}
function overview(){return appointments()+`<section><div class="section-title"><h2>${t('recent')}<span class="count">${filteredVisits().length} ${t('records')}</span></h2>${btn(t('visits'),'nav','arrow','ghost small','data-route="visits"')}</div>${visitList(filteredVisits().slice(0,8))}</section>${canOperate()?`<div class="hint">${icon('shield')}<span>${t('confirmHelp')}</span></div>`:''}`;}
function appointments(){const all=state.data.visits.filter(v=>v.status==='confirmed'&&v.appointment?.date&&v.appointment.status==='scheduled'&&state.person===v.patient_id).sort((a,b)=>a.appointment.date.localeCompare(b.appointment.date));return `<section class="appointment-panel"><div class="section-title"><h2>${t('upcoming')}</h2>${icon('calendar')}</div>${all.length?`<div class="appointment-list">${all.map(v=>{const a=v.appointment,d=dayDiff(a.date),label=d<0?`${t('overdue')} ${-d} ${getLanguage()==='zh-Hans'?'天':'日'}`:d===0?t('today'):d===1?t('tomorrow'):`${d} ${t('daysAfter')}`;return `<div class="appointment-item"><div class="calendar-day"><small>${Number(a.date.slice(5,7))} ${getLanguage()==='zh-Hans'?'月':'月'}</small><strong>${esc(a.date.slice(8))}</strong></div><div class="appointment-text"><strong>${alias(v.patient_id)} · ${esc(v.doctor||v.clinic)}</strong><p>${esc(a.time||'')} ${esc(a.location||v.clinic)}</p>${badge(label,d<0?'danger':d<=7?'pending':'')}</div>${btn(t('details'),'detail','arrow','ghost small',`data-id="${esc(v.id)}"`)}</div>`;}).join('')}</div>`:`<div class="quiet-empty">${icon('calendar')}<div><strong>${t('noAppointments')}</strong><p>${t('appointmentEmpty')}</p></div></div>`}<p class="tiny-status" style="margin-top:12px">${t('refreshNotice')}</p></section>`;}
function empty(){const filtering=state.q||state.from||state.to||state.status!=='all'||(state.route==='medicines'&&state.category!=='all');return `<div class="empty"><div class="empty-icon">${icon(filtering?'search':'book')}</div><h2>${t(filtering?'noResults':canOperate()?'emptyTitle':'emptyFamily')}</h2><p>${t(filtering?'search':canOperate()?'emptyText':'emptyFamilyText')}</p><div class="actions">${filtering?btn(t('clearFilters'),'clear-filters','refresh'):canOperate()?btn(t('scan'),'scan','folder','primary')+btn(t('demoButton'),'demo','arrow'):''}</div></div>`;}
function visitList(visits){if(!visits.length)return empty();return `<div class="ledger"><table><colgroup><col style="width:18%"><col style="width:27%"><col style="width:40%"><col style="width:15%"></colgroup><thead><tr>${['date','doctor','diagnosis','status'].map(k=>`<th scope="col">${t(k)}</th>`).join('')}</tr></thead><tbody>${visits.map(v=>`<tr><td class="date-cell">${esc(dateText(v.date))}</td><td class="doctor-cell"><button class="view-link" data-action="detail" data-id="${esc(v.id)}">${esc(v.doctor||v.clinic||t('unknown'))}</button><small>${esc(v.clinic)}</small></td><td class="diagnosis-cell">${esc(v.diagnosis||v.reason||t('notRecorded'))}<div class="med-summary">${(v.medicines||[]).length} ${t('medsCount')} · ${sourceIds(v).length} ${t('fileCount')}</div></td><td class="visit-status">${statusBadge(v)}</td></tr>`).join('')}</tbody></table><div class="ledger-foot">${visits.length} ${t('records')}</div></div>`;}
function medicinePhotos(m,v){const own=m.source_file_ids?.length,ids=own?m.source_file_ids:v.source_file_ids||[];const photos=[...new Set(ids)].map(id=>state.data.attachments.find(a=>a.id===id&&a.patient_id===v.patient_id&&(canOperate()||a.privacy_checked))).filter(Boolean);return `<div class="medicine-photos">${photos.length?photos.map(a=>`<button type="button" class="medicine-photo ${a.privacy_checked?'':'pending-photo'}" data-action="${!a.privacy_checked&&isLocal()?'redact':'view-file'}" data-id="${esc(a.id)}" aria-label="${esc((a.privacy_checked?t('viewOriginal'):t('fileReview'))+' · '+(a.archive_name||t('source')))}">${a.privacy_checked&&(a.mime?.startsWith('image/')||a.mime==='application/pdf')?`<img data-file="${esc(a.id)}" alt="${esc(m.name||t('source'))}" loading="lazy">`:`${icon(a.privacy_checked?'image':'shield')}<span>${t(a.privacy_checked?'viewOriginal':'photoPending')}</span>`}</button>`).join(''):`<span class="no-photo">${icon('image')}<span>${t('noSource')}</span></span>`}<small class="photo-caption">${photos.length?t(own?'medicinePhoto':'visitPhoto'):''}</small></div>`;}

function medicineCategoryKey(m){return m.category?.trim()?'type:'+fold(m.category.trim()):'uncategorized';}
function medicineRows(){return filteredVisits().flatMap(v=>(v.medicines||[]).map(m=>({v,m})));}
function categoryNav(){const rows=medicineRows(),categories=new Map();for(const {m} of rows){const key=medicineCategoryKey(m);if(!categories.has(key))categories.set(key,{key,label:m.category?.trim()||t('uncategorized'),count:0});categories.get(key).count++;}const options=[{key:'all',label:t('allCategories'),count:rows.length},...[...categories.values()].sort((a,b)=>a.key==='uncategorized'?1:b.key==='uncategorized'?-1:a.label.localeCompare(b.label,getLanguage()))];return `<div class="category-heading">${t('medicineCategory')}</div><nav class="category-nav" aria-label="${t('medicineCategory')}">${options.map(c=>`<button data-action="category" data-value="${esc(c.key)}" class="${state.category===c.key?'active':''}" aria-pressed="${state.category===c.key}"><span>${esc(c.label)}</span><small>${c.count}</small></button>`).join('')}</nav>`;}
function medicineRow({v,m}){return `<article class="med-list-row">${medicinePhotos(m,v)}<div class="medicine-name"><h3>${esc(m.name||t('notRecorded'))}</h3><p>${esc(m.strength)}</p><span class="medicine-type">${esc(m.category?.trim()||t('uncategorized'))}</span>${badge(t(m.status==='current'?'currentMed':m.status==='stopped'?'stoppedMed':'unknownMed'),m.status==='current'?'':'neutral')}</div><div class="medicine-dose"><span class="field-caption">${t('dose')} / ${t('frequency')}</span><p>${esc([m.dose,m.frequency].filter(Boolean).join(' · ')||t('notRecorded'))}</p><p class="medicine-instructions">${esc(m.instructions)}</p></div><div class="medicine-visit"><strong>${esc(v.doctor||v.clinic||t('notRecorded'))}</strong>${btn(t('details'),'detail','arrow','ghost small',`data-id="${esc(v.id)}"`)}</div></article>`;}
function medicineList(){const rows=medicineRows().filter(({m})=>state.category==='all'||medicineCategoryKey(m)===state.category);const groups=new Map();for(const row of rows){const date=row.v.date||'';if(!groups.has(date))groups.set(date,[]);groups.get(date).push(row);}return `<div class="mobile-categories">${categoryNav()}</div><div class="medicine-heading"><span>${t('byDate')} · ${t('newestFirst')}</span><span>${rows.length} ${t('medsCount')} · ${t('photoHelp')}</span></div>${rows.length?[...groups].sort(([a],[b])=>b.localeCompare(a)).map(([date,items])=>`<section class="medicine-date-group" data-date="${esc(date)}"><div class="medicine-date-heading"><h2>${esc(dateText(date))}</h2><span>${items.length} ${t('medsCount')}</span></div><div class="medicine-ledger">${items.map(medicineRow).join('')}</div></section>`).join(''):empty()}<div class="hint">${icon('info')}<span>${t('historical')}</span></div>`;}

function fileCard(a){return `<article class="file-item"><div class="file-preview">${a.privacy_checked&&(a.mime?.startsWith('image/')||a.mime==='application/pdf')?`<img data-file="${esc(a.id)}" alt="${esc(a.archive_name||t('source'))}" loading="lazy">`:icon('image')}</div><div class="file-info"><strong>${esc(a.archive_name||`${alias(a.patient_id)} · ${t('pendingInputs')}`)}</strong><p>${alias(a.patient_id)} · ${esc(fileSummary(a))}</p>${badge(t(a.privacy_checked?'privacyDone':'privacyPending'),a.privacy_checked?'':'pending')}<div class="actions">${btn(t('viewOriginal'),'view-file','image','small',`data-id="${esc(a.id)}"`)}${canOperate()?btn(t('fileReview'),'redact','shield','small',`data-id="${esc(a.id)}"`):''}</div></div></article>`;}
function filesPage(){const items=state.data.attachments.filter(a=>a.patient_id===state.person);return `<div class="upload-zone"><div><h3>${t('upload')}</h3><p>${t('uploadHelp')}</p></div><div class="actions"><select id="upload-person" class="filter-control" aria-label="${t('person')}"><option value="grandpa" ${state.person==='grandpa'?'selected':''}>${t('grandpa')}</option><option value="grandma" ${state.person==='grandma'?'selected':''}>${t('grandma')}</option></select><select id="upload-kind" class="filter-control" aria-label="${t('fileKind')}"><option value="visit">${t('visits')} / ${t('medicines')}</option><option value="report">${t('reports')}</option></select>${btn(t('upload'),'upload','upload','primary')}${btn(t('scan'),'scan','folder')}<input type="file" id="file-input" accept="image/jpeg,image/png,image/webp,application/pdf" multiple hidden></div></div><div class="notice">${t('codexHelp')}<p class="manage-note">${t('privateTemporary')}</p></div>${(state.boot?.paths?.import_folders||[]).length?`<div class="paper-section"><h3>${t('inputFolders')}</h3>${state.boot.paths.import_folders.filter(f=>f.patient_id===state.person).map(f=>`<div class="path-box">${alias(f.patient_id)} · ${esc(f.path)}</div>`).join('')}</div>`:''}${state.boot?.import_folder_warnings?.length?`<div class="notice">${state.boot.import_folder_warnings.map(esc).join('<br>')}</div>`:''}${state.boot?.paths?.inbox?`<div class="hint">${icon('folder')}<span>${esc(state.boot.paths.inbox)}</span>${btn(t('pathCopy'),'copy-path','copy','ghost small')}</div>`:''}<div class="section-title"><h2>${t('source')}<span class="count">${items.length} ${t('fileCount')}</span></h2></div>${items.length?`<div class="file-grid">${items.map(fileCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">${icon('image')}</div><h2>${t('noFiles')}</h2><p>${t('emptyText')}</p></div>`}`;}
function pair(label,value){return `<div class="data-pair"><dt>${t(label)}</dt><dd>${esc(value||t('notRecorded'))}</dd></div>`;}
function renderDetail(){const v=state.data.visits.find(x=>x.id===state.detail&&x.patient_id===state.person);if(!v){state.detail=null;return '';}const a=v.appointment;const files=sourceIds(v).map(id=>state.data.attachments.find(a=>a.id===id)).filter(Boolean);return `${btn(t('back'),'back','left','ghost')}<div class="detail-header"><div><h1>${alias(v.patient_id)} · ${esc(v.doctor||v.clinic||t('visits'))}</h1><p>${esc(dateText(v.date))}${v.clinic?' · '+esc(v.clinic):''}</p><div class="detail-meta">${statusBadge(v)}<span class="profile-age">${esc(patientMeta(v.patient_id))}</span></div></div><div class="actions">${canOperate()?btn(t('edit'),'edit','edit','',`data-id="${esc(v.id)}"`):''}</div></div><div class="detail-grid"><div><section class="paper-section"><h2>${t('diagnosis')}</h2><div class="text-block">${esc(v.diagnosis||t('notRecorded'))}</div><dl>${pair('reason',v.reason)}${pair('notes',v.notes)}</dl>${v.review_notes?`<div class="notice"><strong>${t('reviewNotes')}</strong><p>${esc(v.review_notes)}</p></div>`:''}</section><section class="paper-section"><h2>${t('prescription')}</h2>${(v.medicines||[]).length?`<table class="med-table"><thead><tr>${['medicinePhoto','medicineName','dose','frequency','instructions'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${v.medicines.map(m=>`<tr><td>${medicinePhotos(m,v)}</td><td><strong>${esc(m.name||t('notRecorded'))}</strong><small>${esc(m.strength)}</small><div>${badge(t(m.status==='current'?'currentMed':m.status==='stopped'?'stoppedMed':'unknownMed'),'neutral')}</div></td><td><span class="mobile-label">${t('dose')}</span>${esc(m.dose||t('notRecorded'))}</td><td><span class="mobile-label">${t('frequency')}</span>${esc(m.frequency||t('notRecorded'))}</td><td><span class="mobile-label">${t('instructions')}</span>${esc(m.instructions||t('notRecorded'))}</td></tr>`).join('')}</tbody></table>`:`<p class="muted">${t('notRecorded')}</p>`}<div class="hint">${icon('info')}<span>${t('historical')}</span></div></section>${canOperate()?`<section class="paper-section"><h2>${t('appointment')}</h2>${a?.date?`<dl>${pair('apptDate',dateText(a.date))}${pair('time',a.time)}${pair('place',a.location)}${pair('status',t(a.status||'scheduled'))}${pair('notes',a.notes)}</dl>${isLocal()?btn(t(a.status==='scheduled'?'markComplete':'markScheduled'),'appt-status','check','',`data-id="${esc(v.id)}" data-status="${a.status==='scheduled'?'completed':'scheduled'}"`):''}`:`<p class="muted">${t('notRecorded')}</p>`}</section>`:''}${isLocal()&&v.status!=='confirmed'?`<section class="paper-section"><h2>${t('confirmVisit')}</h2><p class="muted small">${t('confirmHelp')}</p><label class="checkbox" style="margin:18px 0"><input type="checkbox" id="review-consent"><span>${t('reviewConsent')}</span></label>${btn(t('confirmVisit'),'confirm','check','primary',`data-id="${esc(v.id)}"`)}</section>`:''}</div><aside><div class="section-title"><h2>${t('source')}</h2></div><div class="side-files">${files.length?files.map(fileCard).join(''):`<p class="muted small">${t('noSource')}</p>`}</div></aside></div>`;}
function inputField(label,name,value='',type='text',full=false,extra=''){return `<label class="field ${full?'full':''}"><span>${t(label)}</span>${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value??'')}" ${extra}>`}</label>`;}
function renderEditor(){const v=state.editor;return `<div class="editor-max">${btn(t('back'),'back','left','ghost')}<div class="detail-header"><div><h1>${t(v.id?'edit':'newVisit')}</h1><p>${t('noIdentityFields')}</p></div>${badge(t('draft'),'pending')}</div><form id="visit-form"><section class="form-section"><h2>${t('visits')}</h2><div class="form-grid"><label class="field"><span>${t('person')}</span><select name="patient_id">${['grandpa','grandma'].map(p=>`<option value="${p}" ${v.patient_id===p?'selected':''}>${alias(p)}</option>`).join('')}</select></label>${inputField('date','date',v.date,'date')}${inputField('doctor','doctor',v.doctor)}${inputField('clinic','clinic',v.clinic)}${inputField('reason','reason',v.reason,'text',true)}${inputField('diagnosis','diagnosis',v.diagnosis,'textarea',true)}${inputField('notes','notes',v.notes,'textarea',true)}${inputField('reviewNotes','review_notes',v.review_notes,'textarea',true,`placeholder="${t('unresolved')}"`)}</div></section><section class="form-section"><div class="section-title"><h2>${t('prescription')}</h2>${btn(t('addMed'),'add-med','plus','small')}</div><p class="small muted">${t('historical')}</p><div id="medicine-editors">${(v.medicines||[]).map((m,i)=>`<div class="medicine-editor" data-med-index="${i}"><div class="med-edit-head"><strong>${t('prescription')} ${i+1}</strong>${btn(t('remove'),'remove-med','close','ghost small',`data-index="${i}"`)}</div><div class="form-grid">${inputField('medicineName',`med_${i}_name`,m.name)}${inputField('strength',`med_${i}_strength`,m.strength)}${inputField('medicineCategory',`med_${i}_category`,m.category||'','text',false,`placeholder="${t('categoryHelp')}"`)}${inputField('dose',`med_${i}_dose`,m.dose)}${inputField('frequency',`med_${i}_frequency`,m.frequency)}${inputField('instructions',`med_${i}_instructions`,m.instructions)}<label class="field"><span>${t('medicineState')}</span><select name="med_${i}_status">${[['unknown','unknownMed'],['current','currentMed'],['stopped','stoppedMed']].map(([k,l])=>`<option value="${k}" ${m.status===k?'selected':''}>${t(l)}</option>`).join('')}</select></label></div><fieldset class="med-source-picker"><legend>${t('medicinePhoto')}</legend>${state.data.attachments.filter(a=>a.patient_id===v.patient_id).map(a=>`<label class="checkbox"><input type="checkbox" name="med_${i}_source" value="${esc(a.id)}" ${(m.source_file_ids||[]).includes(a.id)?'checked':''}><span>${esc(a.archive_name||a.id.slice(0,8))} ${badge(t(a.privacy_checked?'privacyDone':'privacyPending'),a.privacy_checked?'':'pending')}</span></label>`).join('')||`<p class="muted small">${t('noSource')}</p>`}</fieldset></div>`).join('')}</div></section><section class="form-section"><h2>${t('appointment')}</h2><div class="form-grid">${inputField('apptDate','appointment_date',v.appointment?.date,'date')}${inputField('time','appointment_time',v.appointment?.time,'time')}${inputField('place','appointment_location',v.appointment?.location,'text',true)}${inputField('notes','appointment_notes',v.appointment?.notes,'textarea',true)}</div></section><section class="form-section"><h2>${t('linkSources')}</h2><div class="checkbox-list">${state.data.attachments.filter(a=>a.patient_id===v.patient_id).map(a=>`<label class="checkbox"><input type="checkbox" name="source" value="${esc(a.id)}" ${(v.source_file_ids||[]).includes(a.id)?'checked':''}><span>${esc(a.archive_name||`${alias(a.patient_id)} · ${a.id.slice(0,8)}`)} ${badge(t(a.privacy_checked?'privacyDone':'privacyPending'),a.privacy_checked?'':'pending')}</span></label>`).join('')||`<p class="muted">${t('noFiles')}</p>`}</div></section><div class="form-actions">${btn(t('cancel'),'back') }<button class="btn primary" type="submit">${icon('check')}${t('saveDraft')}</button></div></form></div>`;}
function gatherEditor(){if(state.editorKind==='report')return gatherReportEditor();const f=$('#visit-form');if(!f)return state.editor;const d=new FormData(f),v={...state.editor};for(const key of ['patient_id','date','doctor','clinic','reason','diagnosis','notes','review_notes'])v[key]=String(d.get(key)||'');v.date=v.date||null;v.source_file_ids=d.getAll('source');v.medicines=(v.medicines||[]).map((m,i)=>{const n={...m};for(const k of ['name','strength','category','dose','frequency','instructions','status'])n[k]=String(d.get(`med_${i}_${k}`)||'');n.source_file_ids=d.getAll(`med_${i}_source`).filter(id=>state.data.attachments.some(a=>a.id===id&&a.patient_id===v.patient_id));return n;});v.appointment=d.get('appointment_date')?{date:String(d.get('appointment_date')),time:String(d.get('appointment_time')||''),location:String(d.get('appointment_location')||''),notes:String(d.get('appointment_notes')||''),status:v.appointment?.status||'scheduled'}:null;return v;}
function formatBytes(n){return n==null?'—':n<1000000?`${(n/1000).toFixed(0)} KB`:n<1000000000?`${(n/1000000).toFixed(1)} MB`:`${(n/1000000000).toFixed(2)} GB`;}
function fileSummary(a){return [a.mime==='application/pdf'?'PDF':(a.mime||'').split('/')[1]?.toUpperCase(),formatBytes(a.size),a.pages?`${a.pages} ${t('page')}`:''].filter(Boolean).join(' · ');}
function filteredReports(){return [...(state.data.reports||[])].filter(r=>r.patient_id===state.person&&(canOperate()||r.status==='confirmed')&&(state.status==='all'||r.status===state.status)&&(!state.from||(r.date&&r.date>=state.from))&&(!state.to||(r.date&&r.date<=state.to))&&(!state.q||fold([r.date,r.title,r.category,r.facility,r.doctor,r.summary,r.notes].join(' ')).includes(fold(state.q)))).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.updated_at||'').localeCompare(a.updated_at||''));}
function reportFiles(r){return (r.source_file_ids||[]).map(id=>state.data.attachments.find(a=>a.id===id&&a.patient_id===r.patient_id&&(canOperate()||a.privacy_checked))).filter(Boolean);}
function reportList(){
 const rows=filteredReports();
 if(!rows.length)return `<div class="empty"><div class="empty-icon">${icon('book')}</div><h2>${t(state.q||state.from||state.to?'noResults':'reportsEmpty')}</h2><p>${t('reportsEmptyHelp')}</p>${canOperate()?btn(t('newReport'),'new-report','plus','primary'):''}</div>`;
 return `<div class="report-list">${rows.map(r=>{const files=reportFiles(r),cover=files.find(a=>a.privacy_checked);return `<article class="report-row"><button class="report-cover" data-action="report-detail" data-id="${esc(r.id)}" aria-label="${esc(r.title)}">${cover?`<img data-file="${esc(cover.id)}" alt="${esc(r.title)}" loading="lazy">`:icon('book')}</button><div class="report-copy"><time>${esc(dateText(r.date))}</time><h2><button class="view-link" data-action="report-detail" data-id="${esc(r.id)}">${esc(r.title||t('reports'))}</button></h2><p>${esc([r.category,r.facility,r.doctor].filter(Boolean).join(' · ')||t('notRecorded'))}</p>${r.summary?`<p class="report-summary">${esc(r.summary)}</p>`:''}<div class="report-file-meta">${files.length} ${t('fileCount')} · ${formatBytes(files.reduce((n,a)=>n+(a.size||0),0))}${canOperate()?` · ${statusBadge(r)}`:''}</div></div>${btn(t('details'),'report-detail','arrow','ghost small',`data-id="${esc(r.id)}"`)}</article>`;}).join('')}</div>`;
}
function renderReportDetail(){
 const r=(state.data.reports||[]).find(r=>r.id===state.detail&&r.patient_id===state.person&&(canOperate()||r.status==='confirmed'));if(!r){state.detail=null;return '';}
 return `${btn(t('back'),'back','left','ghost')}<header class="detail-header"><div><h1>${esc(r.title)}</h1><p>${alias(r.patient_id)} · ${esc(dateText(r.date))}</p>${canOperate()?statusBadge(r):''}</div>${canOperate()?btn(t('edit'),'edit-report','edit','',`data-id="${esc(r.id)}"`):''}</header><div class="detail-grid"><div><section class="paper-section"><h2>${t('reportSummary')}</h2><div class="text-block">${esc(r.summary||t('notRecorded'))}</div><dl>${pair('reportCategory',r.category)}${pair('facility',r.facility)}${pair('doctor',r.doctor)}${pair('notes',r.notes)}</dl>${canOperate()&&r.review_notes?`<div class="notice">${esc(r.review_notes)}</div>`:''}</section>${isLocal()&&r.status!=='confirmed'?`<section class="paper-section"><h2>${t('confirmReport')}</h2><p>${t('reportNaming')}</p><label class="checkbox report-consent"><input type="checkbox" id="report-consent"><span>${t('reportConsent')}</span></label>${btn(t('confirmReport'),'confirm-report','check','primary',`data-id="${esc(r.id)}"`)}</section>`:''}</div><aside><div class="section-title"><h2>${t('source')}</h2></div><div class="side-files">${reportFiles(r).map(fileCard).join('')||`<p class="muted">${t('noSource')}</p>`}</div></aside></div>`;
}
function renderReportEditor(){
 const r=state.editor;
 return `<div class="editor-max">${btn(t('back'),'back','left','ghost')}<header class="detail-header"><div><h1>${t(r.id?'edit':'newReport')}</h1><p>${t('reportHelp')}</p></div>${badge(t('draft'),'pending')}</header><form id="report-form"><section class="form-section"><div class="form-grid"><label class="field"><span>${t('person')}</span><select name="patient_id">${['grandpa','grandma'].map(p=>`<option value="${p}" ${r.patient_id===p?'selected':''}>${alias(p)}</option>`).join('')}</select></label>${inputField('reportDate','date',r.date,'date')}${inputField('reportTitle','title',r.title,'text',true,'maxlength="120" required')}${inputField('reportCategory','category',r.category)}${inputField('facility','facility',r.facility)}${inputField('doctor','doctor',r.doctor)}${inputField('reportSummary','summary',r.summary,'textarea',true)}${inputField('notes','notes',r.notes,'textarea',true)}${inputField('reviewNotes','review_notes',r.review_notes,'textarea',true)}</div></section><section class="form-section"><h2>${t('reportSources')}</h2><p>${t('reportNaming')}</p><div class="checkbox-list">${state.data.attachments.filter(a=>a.patient_id===r.patient_id).map(a=>`<label class="checkbox"><input type="checkbox" name="source" value="${esc(a.id)}" ${(r.source_file_ids||[]).includes(a.id)?'checked':''}><span>${esc(a.archive_name||a.id.slice(0,12))}<small> ${esc(fileSummary(a))} </small>${badge(t(a.privacy_checked?'privacyDone':'privacyPending'),a.privacy_checked?'':'pending')}</span></label>`).join('')||`<p class="muted">${t('noFiles')}</p>`}</div></section><div class="form-actions">${btn(t('cancel'),'back')}<button class="btn primary" type="submit">${icon('check')}${t('saveDraft')}</button></div></form></div>`;
}
function gatherReportEditor(){const f=$('#report-form');if(!f)return state.editor;const d=new FormData(f),r={...state.editor};for(const key of ['patient_id','date','title','category','facility','doctor','summary','notes','review_notes'])r[key]=String(d.get(key)||'');r.date=r.date||null;r.source_file_ids=d.getAll('source').filter(id=>state.data.attachments.some(a=>a.id===id&&a.patient_id===r.patient_id));return r;}
function storagePanel(){
 const data=state.storage,c=data?.cloud,l=data?.local;
 const stat=(label,n,max)=>`<div class="storage-stat"><span>${t(label)}</span><strong>${formatBytes(n)}${max?` <small>/ ${formatBytes(max)}</small>`:''}</strong>${max&&n!=null?`<meter min="0" max="${max}" value="${Math.min(n,max)}" high="${max*.8}" optimum="0" aria-label="${t(label)}"></meter>`:''}</div>`;
 return `<section class="paper-section full"><div class="section-title"><h2>${t('storage')}</h2>${btn(t('refresh'),'storage-refresh','refresh','small')}</div><div id="storage-content">${!data?`<p class="muted">${t('loading')}</p>`:`${c?.available?`<div class="storage-stats">${stat('cloudFiles',c.bucket_bytes,c.file_quota_bytes)}${stat('cloudDatabase',c.database_bytes,c.database_quota_bytes)}</div><p class="manage-note">${t('storageHistory')}：${c.retained_versions??'—'} · ${esc(formatStamp(c.measured_at))}</p>${c.file_warning||c.database_warning?`<div class="notice">${t('storageWarning')}</div>`:''}`:`<p>${t(c?.configured?'storageUnavailable':'notConnected')}</p>`}<div class="storage-stats local-storage">${stat('localArchive',l?.archive_bytes)}${stat('localBackups',l?.backup_bytes)}</div><p class="manage-note">${t('storageQuotaNote')}</p>`}</div><p class="manage-note">${t('storageHelp')}</p><p class="manage-note">${t('storageLocalNote')}</p></section>`;
}
async function loadStorageStatus(){if(!isLocal())return;const epoch=dataEpoch;try{const result=await api('/storage');if(epoch!==dataEpoch||!isLocal())return;state.storage=result;}catch{if(epoch!==dataEpoch||!isLocal())return;state.storage={cloud:{configured:true,available:false}};}if(state.route==='settings'&&!state.editor&&!state.detail)renderWorkspace();}

async function showPdfReview(a){
 const epoch=++dialogEpoch;redaction=null;const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${t('fileReview')} · PDF</h2>${btn(t('cancel'),'close-dialog','close','icon-only')}</div><div class="dialog-body"><p>${t('loading')}</p></div>`;d.showModal();
 const info=await api(`/files/${encodeURIComponent(a.id)}/pdf-info`);if(epoch!==dialogEpoch||!d.open)return;
 $('.dialog-body',d).innerHTML=`<p>${t('pdfReviewHelp')}</p><div class="pdf-controls">${btn(t('back'),'pdf-prev','left','small')}<label>${t('page')} <select id="pdf-page" class="filter-control">${Array.from({length:info.pages},(_,i)=>`<option value="${i}">${i+1} / ${info.pages}</option>`).join('')}</select></label>${btn(t('nextPage'),'pdf-next','arrow','small')}<span id="pdf-progress" role="status"></span></div><div class="canvas-wrap"><canvas id="redact-canvas" aria-label="${t('redact')}"></canvas></div>${btn(t('undoMask'),'undo-mask','left','small')}<label class="checkbox report-consent"><input id="pdf-reviewed" type="checkbox" disabled><span>${t('pageReviewed')}</span></label><div class="dialog-actions">${btn(t('saveSafePdf'),'save-pdf','check','primary',`data-id="${esc(a.id)}" disabled`)}</div>`;
 redaction={pdf:true,id:a.id,epoch,info,page:0,loadEpoch:0,loading:true,reviewed:new Set(),pageBoxes:new Map(),pageSizes:new Map(),c:$('#redact-canvas'),boxes:[],img:null,current:null,start:null};
 const c=redaction.c;
 c.addEventListener('pointerdown',e=>{const r=redaction;if(!r?.pdf||r.c!==c||r.loading)return;c.setPointerCapture(e.pointerId);r.reviewed.delete(r.page);r.start=canvasPoint(e);r.current=null;updatePdfReview();});
 c.addEventListener('pointermove',e=>{const r=redaction;if(!r?.pdf||r.c!==c||!r.start||r.loading)return;const p=canvasPoint(e);r.current=[r.start[0],r.start[1],p[0]-r.start[0],p[1]-r.start[1]];drawMasks();});
 c.addEventListener('pointerup',()=>{const r=redaction;if(!r?.pdf||r.c!==c||r.loading)return;if(r.current&&Math.abs(r.current[2])>2&&Math.abs(r.current[3])>2)r.boxes.push(r.current);r.start=null;r.current=null;drawMasks();updatePdfReview();});
 c.addEventListener('pointercancel',()=>{if(!redaction?.pdf||redaction.c!==c)return;redaction.start=null;redaction.current=null;drawMasks();});
 await loadPdfPage(0);
}
function updatePdfReview(){const r=redaction;if(!r?.pdf)return;const checkbox=$('#pdf-reviewed');if(checkbox){checkbox.disabled=r.loading||Boolean(r.start);checkbox.checked=r.reviewed.has(r.page);}const save=$('[data-action="save-pdf"]');if(save)save.disabled=r.loading||r.reviewed.size!==r.info.pages||Boolean(r.start);const progress=$('#pdf-progress');if(progress)progress.textContent=`${r.reviewed.size} / ${r.info.pages} ${t('pagesReviewed')}`;const prev=$('[data-action="pdf-prev"]'),next=$('[data-action="pdf-next"]');if(prev)prev.disabled=r.page===0;if(next)next.disabled=r.page>=r.info.pages-1;}
async function loadPdfPage(page){
 const r=redaction;if(!r?.pdf||!Number.isInteger(page)||page<0||page>=r.info.pages)return;
 const loadEpoch=++r.loadEpoch;r.page=page;r.loading=true;r.start=null;r.current=null;r.c.hidden=true;$('#pdf-page').value=String(page);updatePdfReview();
 try{const img=new Image();img.src=`/api/files/${encodeURIComponent(r.id)}/page/${page}?source=${encodeURIComponent(r.info.sha256)}`;await img.decode();if(redaction!==r||r.epoch!==dialogEpoch||loadEpoch!==r.loadEpoch||!$('#dialog').open)return;r.img=img;r.c.width=img.naturalWidth;r.c.height=img.naturalHeight;r.pageSizes.set(page,[r.c.width,r.c.height]);if(!r.pageBoxes.has(page))r.pageBoxes.set(page,[]);r.boxes=r.pageBoxes.get(page);r.c.hidden=false;r.loading=false;drawMasks();updatePdfReview();}catch(err){if(redaction!==r||loadEpoch!==r.loadEpoch)return;r.loading=true;updatePdfReview();throw err;}
}
async function savePdfReview(id){
 const r=redaction;if(!r?.pdf||r.id!==id||r.loading||r.start||r.reviewed.size!==r.info.pages)throw Error(t('pdfReviewAll'));
 const pages=[...r.pageBoxes].map(([page,boxes])=>{const [width,height]=r.pageSizes.get(page);return {page,boxes:boxes.map(([x,y,w,h])=>{const left=Math.max(0,Math.min(x,x+w)),top=Math.max(0,Math.min(y,y+h)),right=Math.min(width,Math.max(x,x+w)),bottom=Math.min(height,Math.max(y,y+h));return {x:left/width,y:top/height,w:(right-left)/width,h:(bottom-top)/height};}).filter(b=>b.w>0&&b.h>0)};});
 await api(`/files/${encodeURIComponent(id)}/sanitize-pdf`,{source_sha256:r.info.sha256,pages,reviewed_pages:[...r.reviewed].sort((a,b)=>a-b),privacy_checked:true});
 if(redaction===r){++dialogEpoch;$('#dialog').close();redaction=null;}clearUrls();await loadData();render();toast(t('saved'));
}
function sharePanel(){
 const share=state.share,active=share?.status==='active'&&share.verified&&share.url;
 return `<section class="paper-section full"><h2>${t('shareTitle')}</h2><p>${t('shareHelp')}</p><p class="manage-note">${t('sharePrivacy')}</p>${share?.status==='unavailable'?`<div class="notice">${t('shareCheckFailed')}</div>`:''}${active?`<label class="field share-link-field"><span>${t('shareLink')}</span><input readonly value="${esc(share.url)}" aria-label="${t('shareLink')}" autocomplete="off" spellcheck="false"></label><div class="actions">${btn(t('shareCopy'),'share-copy','copy','primary')}${btn(t('shareRotate'),'share-rotate','refresh')}${btn(t('shareRevoke'),'share-revoke','close')}</div>`:`<p class="manage-note">${t(share?.status==='revoked'?'shareStopped':share?.status==='expired'?'shareExpired':share?'shareNotCreated':'loading')}</p><div class="actions">${share&&share.status!=='unavailable'&&share.configured?btn(t('shareCreate'),'share-create','arrow','primary'):''}${btn(t('refresh'),'share-refresh','refresh')}</div>`}</section>`;
}
async function loadShareStatus(){
 try{state.share=await api('/share');}catch{state.share={status:'unavailable',verified:false};}
 if(isLocal()&&state.route==='settings')renderWorkspace();
}
function shareConfirm(action){
 const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${t(action==='rotate'?'shareRotate':'shareRevoke')}</h2>${btn(t('cancel'),'close-dialog','close','icon-only')}</div><div class="dialog-body"><p>${t(action==='rotate'?'shareRotateConfirm':'shareRevokeConfirm')}</p><div class="dialog-actions">${btn(t('cancel'),'close-dialog')}${btn(t(action==='rotate'?'shareRotate':'shareRevoke'),'share-'+action+'-apply','check','primary')}</div></div>`;d.showModal();
}
function settingsPage(){const pending=[...state.data.visits,...(state.data.reports||[])].filter(v=>v.status!=='confirmed').length,raw=state.data.attachments.filter(a=>!a.privacy_checked).length;return `<div class="settings-grid"><section class="paper-section full"><h2>${t('profiles')}</h2><p>${t('profileHelp')}</p>${state.data.patients.filter(p=>p.id===state.person).map(p=>`<form class="profile-form" data-patient="${esc(p.id)}"><strong>${alias(p.id)}</strong>${inputField('age','age',p.age,'number',false,'min="0" max="125"')}<label class="field"><span>${t('sex')}</span><select name="sex">${['unknown','male','female'].map(v=>`<option value="${v}" ${p.sex===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><button class="btn" type="submit">${t('save')}</button></form>`).join('')}</section><section class="paper-section"><h2>${t('backupTitle')}</h2><p>${t('backupHelp')}</p>${pending||raw?`<div class="notice">${pending} ${t('pendingCount')} · ${raw} ${t('privacyPending')}<br>${t('backupsExcluded')}</div>`:''}${btn(t('backup'),'backup','download','primary')}<p class="manage-note">${t('lastBackup')}：${esc(formatStamp(state.boot?.last_backup))}</p><div id="backup-result"></div></section><section class="paper-section"><h2>${t('restore')}</h2><p>${t('restoreHelp')}</p>${btn(t('restore'),'restore','upload')}<input type="file" id="restore-input" accept=".zip,application/zip" hidden></section>${storagePanel()}${sharePanel()}<section class="paper-section full"><h2>${t('sync')}</h2><p>${t('syncHelp')}</p><div class="actions">${badge(t(state.boot?.cloud?.configured?'connected':'notConnected'),state.boot?.cloud?.configured?'':'pending')}${btn(t('export'),'export','upload')}</div><p class="manage-note">${t('exportHelp')}</p><p class="manage-note">${t('lastSync')}：${esc(formatStamp(state.boot?.last_sync))}</p></section></div>`;}
function renderAuth(){if(state.mode==='share-denied'){$('#app').innerHTML=`<main class="initial">${brand()}<h1>${t('shareUnavailableTitle')}</h1><p>${esc(state.error||t('shareUnavailable'))}</p>${btn(t('retry'),'reload','refresh')}<button class="language" data-action="language">繁體 / 简体</button></main>`;return;}const setup=state.mode==='setup';$('#app').innerHTML=`<div class="auth-shell"><section class="auth-story"><div class="brand"><img src="./icon.svg" alt=""><div><strong>${t('app')}</strong><small>${t('subtitle')}</small></div></div><div><h1>${t('loginTitle')}</h1><p>${t('loginHelp')}</p><div class="auth-lines"><div>${icon('book')}${t('visits')} · ${t('diagnosis')}</div><div>${icon('pill')}${t('prescription')} · ${t('source')}</div><div>${icon('calendar')}${t('upcoming')}</div></div></div><div class="auth-foot">${t('privacyFoot')} · ${t('readOnly')}</div></section><section class="auth-main"><button class="language" data-action="language">繁體 / 简体</button><div class="auth-form"><h2>${t(setup?'setupTitle':'login')}</h2><p>${t(setup?'setupText':'loginHelp')}</p>${setup?`<div class="hint">${icon('shield')}<span>${t('noIdentityFields')}</span></div>${btn(t('demoButton'),'demo','arrow')}`:`<form id="login-form"><label class="field"><span>${t('email')}</span><input type="email" name="email" autocomplete="username" required></label><label class="field"><span>${t('password')}</span><input type="password" name="password" autocomplete="current-password" required></label><button type="submit" class="btn primary">${t('login')}${icon('arrow')}</button></form>`}<div class="auth-error" role="alert">${esc(state.error||'')}</div><div class="footnote">${t('refreshNotice')}</div></div></section></div>`;}
async function fileUrl(a,thumbnail=false){const key=a.id+(thumbnail?':thumbnail':':original');if(state.urls.has(key))return state.urls.get(key);const epoch=dataEpoch,mode=state.mode;const u=mode==='local'?`/api/files/${encodeURIComponent(a.id)}${thumbnail?'/thumbnail':''}`:await (thumbnail?state.client.thumbnailUrl(a):state.client.fileUrl(a));if(epoch!==dataEpoch||mode!==state.mode)throw Error(t('reloadWarning'));state.urls.set(key,u);return u;}
function clearUrls(){for(const u of state.urls.values())if(u.startsWith('blob:'))URL.revokeObjectURL(u);state.urls.clear();}
async function loadThumbnails(){for(const img of $$('img[data-file]')){const a=state.data.attachments.find(a=>a.id===img.dataset.file&&a.patient_id===state.person&&a.privacy_checked);if(!a)continue;try{img.src=await fileUrl(a,true);}catch{img.alt=t('failed');}}}
async function showRedaction(id){const a=state.data.attachments.find(a=>a.id===id);if(!a)return;if(a.mime==='application/pdf')return showPdfReview(a);if(!a.mime?.startsWith('image/'))throw Error(t('uploadHelp'));const epoch=++dialogEpoch;redaction=null;const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${t('redact')}</h2>${btn(t('cancel'),'close-dialog','close','icon-only')}</div><div class="dialog-body"><p>${t('maskHelp')}</p><div class="canvas-wrap"><canvas id="redact-canvas" aria-label="${t('redact')}"></canvas></div>${btn(t('undoMask'),'undo-mask','left','small')}<label class="checkbox"><input id="mask-consent" type="checkbox"><span>${t('maskConsent')}</span></label><div class="dialog-actions">${btn(t('noIdentity'),'privacy-clean','check','',`data-id="${esc(id)}"`)}${btn(t('saveMasked'),'save-mask','mask','primary',`data-id="${esc(id)}"`)}</div></div>`;d.showModal();const img=new Image();img.src=await fileUrl(a);await img.decode();if(epoch!==dialogEpoch||!d.open)return;const c=$('#redact-canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;redaction={id,img,c,boxes:[],start:null,current:null};drawMasks();c.addEventListener('pointerdown',e=>{if(!redaction||redaction.c!==c)return;$('#mask-consent').checked=false;c.setPointerCapture(e.pointerId);redaction.start=canvasPoint(e);redaction.current=null;});c.addEventListener('pointermove',e=>{if(!redaction?.start)return;const p=canvasPoint(e);redaction.current=[redaction.start[0],redaction.start[1],p[0]-redaction.start[0],p[1]-redaction.start[1]];drawMasks();});c.addEventListener('pointerup',()=>{if(!redaction||redaction.c!==c)return;if(redaction.current&&Math.abs(redaction.current[2])>2&&Math.abs(redaction.current[3])>2)redaction.boxes.push(redaction.current);redaction.start=null;redaction.current=null;drawMasks();});c.addEventListener('pointercancel',()=>{if(!redaction||redaction.c!==c)return;redaction.start=null;redaction.current=null;drawMasks();});}
function canvasPoint(e){const r=redaction.c.getBoundingClientRect();return [(e.clientX-r.left)*redaction.c.width/r.width,(e.clientY-r.top)*redaction.c.height/r.height];}
function drawMasks(){if(!redaction)return;const {c,img,boxes,current}=redaction,x=c.getContext('2d');x.drawImage(img,0,0);x.fillStyle='#17211c';for(const b of [...boxes,...(current?[current]:[])])x.fillRect(...b);const clean=$('[data-action=privacy-clean]',$('#dialog'));if(clean)clean.disabled=Boolean(boxes.length||current);}
async function bytesBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
async function mutateRefresh(path,body,message=t('saved')){await api(path,body);clearUrls();await loadData();render();toast(message);}
async function act(action,e){const el=e.target.closest('[data-action]');if(state.busy&&!['close-dialog'].includes(action))return;
 if(action==='language'){if(state.editor)state.editor=gatherEditor();setLanguage(getLanguage()==='zh-Hant'?'zh-Hans':'zh-Hant');render();return;}
 if(action==='nav'){if(!(canOperate()?['overview','visits','medicines','reports','files','settings']:['visits','medicines','reports']).includes(el.dataset.route))return;state.editor=null;state.detail=null;state.route=el.dataset.route;render();if(isLocal()&&state.route==='settings')await Promise.all([loadShareStatus(),loadStorageStatus()]);return;}
 if(action==='chapter'){if(!['grandpa','grandma'].includes(el.dataset.id))return;state.person=el.dataset.id;state.route=canOperate()?'overview':'visits';state.category='all';state.detail=null;state.editor=null;state.q='';state.from='';state.to='';state.status='all';render();window.scrollTo(0,0);return;}
 if(action==='chapters'){state.person=null;state.editor=null;state.detail=null;render();window.scrollTo(0,0);return;}
 if(action==='category'){state.category=el.dataset.value||'all';renderBody();return;}
 if(action==='clear-filters'){state.category='all';state.q='';state.from='';state.to='';state.status='all';render();return;}
 if(action==='report-detail'){if(!(state.data.reports||[]).some(r=>r.id===el.dataset.id&&r.patient_id===state.person))return;state.editor=null;state.detailKind='report';state.detail=el.dataset.id;renderWorkspace();window.scrollTo(0,0);return;}
 if(action==='detail'){state.detailKind='visit';if(!state.data.visits.some(v=>v.id===el.dataset.id&&v.patient_id===state.person))return;state.editor=null;state.detail=el.dataset.id;renderWorkspace();window.scrollTo(0,0);return;}
 if(action==='back'){state.editor=null;state.detail=null;renderWorkspace();window.scrollTo(0,0);return;}
 if(action==='demo'){state.demo=true;state.mode='local';state.person=null;state.data=sampleData();state.error=null;render();return;}
 if(action==='exit-demo'){location.href=location.pathname;return;}
 if(action==='close-dialog'){++dialogEpoch;$('#dialog').close();redaction=null;return;}
 if(action==='pdf-prev'||action==='pdf-next'){if(redaction?.pdf)await loadPdfPage(redaction.page+(action==='pdf-prev'?-1:1));return;}
 if(action==='undo-mask'){redaction?.boxes.pop();if(redaction?.pdf){redaction.reviewed.delete(redaction.page);updatePdfReview();}if($('#mask-consent'))$('#mask-consent').checked=false;drawMasks();return;}
 if(action==='view-file'){const a=state.data.attachments.find(a=>a.id===el.dataset.id&&a.patient_id===state.person&&(canOperate()||a.privacy_checked));if(!a)return;const epoch=++dialogEpoch,d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${t('source')}</h2>${btn(t('back'),'close-dialog','close','icon-only')}</div><div class="dialog-body photo-viewer"><p>${t('loading')}</p></div>`;d.showModal();const url=await fileUrl(a);if(epoch!==dialogEpoch||!d.open)return;$('.dialog-body',d).innerHTML=`<div class="photo-toolbar"><span>${esc(a.archive_name||t('source'))}</span><a class="btn small" href="${esc(url)}" target="_blank" rel="noopener">${t(a.mime==='application/pdf'?'openPdf':'openFullImage')}${icon('arrow')}</a></div>${a.mime?.startsWith('image/')?`<img class="full-photo" src="${esc(url)}" alt="${esc(a.archive_name||t('source'))}">`:`<object class="pdf-viewer" data="${esc(url)}" type="application/pdf"><p>${t('pdfOpenHelp')}</p></object>`}`;return;}
 if(action==='reload'){state.error=null;if(state.mode==='local'||state.mode==='cloud'||state.mode==='share'){await loadData();render();}else await init();return;}
 if(action==='logout'){const client=state.client;clearPrivateView();await client.signOut();return;}
 if(state.demo)throw Error(t('sampleOnly'));
 if(!isLocal())throw Error(t('readOnly'));
 if(action==='share-refresh'){await loadShareStatus();return;}
 if(action==='share-copy'){if(state.share?.status!=='active'||!state.share?.verified||!state.share?.url)throw Error(t('shareCheckFailed'));await navigator.clipboard.writeText(state.share.url);toast(t('copied'));return;}
 if(action==='share-rotate'||action==='share-revoke'){shareConfirm(action.slice(6));return;}
 if(['share-create','share-rotate-apply','share-revoke-apply'].includes(action)){const op=action==='share-create'?'create':action==='share-rotate-apply'?'rotate':'revoke';state.share=await api('/share/'+op,{});$('#dialog').close();renderWorkspace();toast(t('saved'));return;}
 if(action==='new-report'){state.detail=null;state.editorKind='report';state.editor={patient_id:state.person,date:null,title:'',category:'',facility:'',doctor:'',summary:'',notes:'',review_notes:'',source_file_ids:[]};renderWorkspace();return;}
 if(action==='edit-report'){const r=(state.data.reports||[]).find(r=>r.id===el.dataset.id&&r.patient_id===state.person);if(!r)return;state.editorKind='report';state.editor=structuredClone(r);state.detail=null;renderWorkspace();return;}
 if(action==='confirm-report'){if(!$('#report-consent')?.checked)throw Error(t('reportConsent'));await mutateRefresh(`/reports/${encodeURIComponent(el.dataset.id)}/confirm`,{reviewed:true});return;}
 if(action==='storage-refresh'){await loadStorageStatus();return;}
 if(action==='save-pdf'){await savePdfReview(el.dataset.id);return;}
 if(action==='new'){state.editorKind='visit';state.detail=null;state.editor={patient_id:state.person==='grandma'?'grandma':'grandpa',date:null,doctor:'',clinic:'',diagnosis:'',reason:'',notes:'',review_notes:'',medicines:[],source_file_ids:[],appointment:null};renderWorkspace();return;}
 if(action==='edit'){state.editorKind='visit';const selected=state.data.visits.find(v=>v.id===el.dataset.id&&v.patient_id===state.person);if(!selected)return;state.editor=structuredClone(selected);state.detail=null;renderWorkspace();return;}
 if(action==='add-med'){state.editor=gatherEditor();state.editor.medicines.push({id:uuid(),name:'',strength:'',category:'',dose:'',frequency:'',instructions:'',status:'unknown',source_file_ids:[]});renderWorkspace();return;}
 if(action==='remove-med'){state.editor=gatherEditor();state.editor.medicines.splice(Number(el.dataset.index),1);renderWorkspace();return;}
 if(action==='scan'){const res=await api('/scan',{});await loadData();state.route='files';state.detail=null;state.editor=null;render();toast(`${t('pendingInputs')}：${res.imported??res.imported_count??0} · ${t('codexHelp')}`);return;}
 if(action==='upload'){$('#file-input').click();return;}
 if(action==='copy-path'){await navigator.clipboard.writeText(state.boot.paths.inbox);toast(t('copied'));return;}
 if(action==='redact'){await showRedaction(el.dataset.id);return;}
 if(action==='save-mask'||action==='privacy-clean'){if(!redaction||redaction.id!==el.dataset.id)throw Error(t('reloadWarning'));if(action==='privacy-clean'&&(redaction.boxes.length||redaction.current))throw Error(t('useMaskedSave'));if(!$('#mask-consent')?.checked)throw Error(t('maskConsent'));if(action==='save-mask'&&!redaction.boxes.length)throw Error(t('maskHelp'));if(action==='privacy-clean')await api(`/files/${encodeURIComponent(el.dataset.id)}/privacy`,{reviewed:true});else await api(`/files/${encodeURIComponent(el.dataset.id)}/sanitize`,{content_base64:redaction.c.toDataURL('image/png').split(',')[1],mime:'image/png',privacy_checked:true});$('#dialog').close();redaction=null;clearUrls();await loadData();render();toast(t('saved'));return;}
 if(action==='confirm'){if(!$('#review-consent')?.checked)throw Error(t('reviewConsent'));await mutateRefresh(`/visits/${encodeURIComponent(el.dataset.id)}/confirm`,{reviewed:true});return;}
 if(action==='appt-status'){await mutateRefresh(`/appointments/${encodeURIComponent(el.dataset.id)}`,{status:el.dataset.status});return;}
 if(action==='backup'){const r=await api('/backup',{});state.boot=await api('/bootstrap');render();const target=$('#backup-result');if(target)target.innerHTML=`<p class="manage-note">${esc(r.name||r.path||'')}</p><a class="btn small" href="/api/backups/${encodeURIComponent(r.name)}" download>${icon('download')}${t('downloadBackup')}</a>`;toast(t('saved'));return;}
 if(action==='restore'){$('#restore-input').click();return;}
 if(action==='restore-apply'){await api('/restore/apply',{token:el.dataset.token});$('#dialog').close();clearUrls();await loadData();state.boot=await api('/bootstrap');render();toast(t('saved'));return;}
 if(action==='export'){const r=await api('/export',{});toast(`${t('saved')} · ${r.path||r.name||t('exportHelp')}`);return;}
}
const mutationActions=new Set(['scan','save-mask','save-pdf','privacy-clean','confirm','confirm-report','appt-status','backup','restore-apply','export','share-create','share-rotate-apply','share-revoke-apply']);
document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-action]');if(!target)return;
 const mutating=mutationActions.has(target.dataset.action);
 if(mutating&&actionInFlight)return;
 if(mutating){actionInFlight=true;target.disabled=true;}
 try{await act(target.dataset.action,e);}catch(error){toast(error.message||t('failed'),true);}
 finally{if(mutating){actionInFlight=false;if(target.isConnected)target.disabled=false;}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.q=e.target.value;renderBody();}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='pdf-page'){await loadPdfPage(Number(el.value));return;}if(el.id==='pdf-reviewed'){if(!redaction?.pdf||redaction.loading)return;if(el.checked)redaction.reviewed.add(redaction.page);else redaction.reviewed.delete(redaction.page);updatePdfReview();return;}if(el.id==='from'||el.id==='to'){state[el.id]=el.value;renderBody();}if(el.id==='status-filter'){state.status=el.value;renderBody();}if(el.name==='patient_id'&&state.editor){state.editor=gatherEditor();state.editor.source_file_ids=[];for(const med of state.editor.medicines||[])med.source_file_ids=[];renderWorkspace();}if(el.id==='file-input'){if(!isLocal())throw Error(t('readOnly'));state.busy=true;let count=0;for(const file of el.files){if(file.size>(file.type==='application/pdf'?50000000:25*1024*1024))throw Error(t('fileTooLarge'));await api('/upload',{patient_id:$('#upload-person').value,kind:$('#upload-kind').value,name:file.name,content_base64:await bytesBase64(file)});count++;}await loadData();render();toast(`${t('saved')} · ${count} ${t('fileCount')}`);}if(el.id==='restore-input'&&el.files[0]){if(!isLocal())throw Error(t('readOnly'));state.busy=true;const file=el.files[0];if(file.size>512*1024*1024)throw Error(t('backupTooLarge'));const r=await api('/restore/preview',{content_base64:await bytesBase64(file)});const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${t('restore')}</h2>${btn(t('cancel'),'close-dialog','close','icon-only')}</div><div class="dialog-body"><p>${t('restoreHelp')}</p><dl>${pair('date',formatStamp(r.created_at))}${pair('visits',String(r.visits))}${pair('reports',String(r.reports||0))}${pair('source',String(r.attachments))}</dl><div class="dialog-actions">${btn(t('cancel'),'close-dialog')}${btn(t('restoreApply'),'restore-apply','check','primary',`data-token="${esc(r.token)}"`)}</div></div>`;d.showModal();}}catch(err){toast(err.message||t('failed'),true);}finally{state.busy=false;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['visit-form','report-form','login-form'].includes(f.id)&&!f.matches('.profile-form'))return;e.preventDefault();if(state.busy)return;state.busy=true;const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{if(f.id==='report-form'){if(!isLocal())throw Error(t('readOnly'));const r=gatherReportEditor();const res=await api('/reports',r);state.editor=null;await loadData();state.person=r.patient_id;state.detailKind='report';state.detail=res.id||res.report?.id||r.id||null;render();toast(t('saved'));}else if(f.id==='visit-form'){state.detailKind='visit';if(!isLocal())throw Error(t('readOnly'));const v=gatherEditor();const res=await api('/visits',v);state.editor=null;await loadData();state.person=v.patient_id;state.detail=res.id||res.visit?.id||v.id||null;render();toast(t('saved'));}else if(f.id==='login-form'){const d=new FormData(f);await state.client.signIn(String(d.get('email')).trim(),String(d.get('password')));state.mode='cloud';await loadData();state.error=null;render();}else{if(state.demo)throw Error(t('sampleOnly'));
 if(!isLocal())throw Error(t('readOnly'));const d=new FormData(f);await api('/patients',{id:f.dataset.patient,age:d.get('age')===''?null:Number(d.get('age')),sex:String(d.get('sex'))});await loadData();render();toast(t('saved'));}}catch(err){if(f.id==='login-form'){state.mode='login';state.error=err.message;render();}else toast(err.message||t('failed'),true);}finally{state.busy=false;if(submit?.isConnected)submit.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(state.editor){e.preventDefault();e.returnValue='';}});
function sampleData(){const result=sampleArchive();if(state.view==='family')result.visits=result.visits.filter(v=>v.status==='confirmed');return result;}
function sampleArchive(){const d=new Date(today()+'T12:00:00Z');const offset=n=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10);};return {schema_version:1,patients:[{id:'grandpa',name:'爺爺',age:null,sex:'male'},{id:'grandma',name:'嬷嬷',age:null,sex:'female'}],visits:[{id:'demo-1',patient_id:'grandpa',date:offset(-4),doctor:'陳醫生（示範）',clinic:'家庭診所（示範）',diagnosis:'診斷內容會按照醫生紙原文整理。',reason:'定期覆診（示範）',notes:'這是畫面示範，不是真實病歷。',status:'confirmed',medicines:[{id:'demo-m1',name:'示範藥品 A',strength:'按藥袋原文',dose:'按處方原文',frequency:'按處方原文',instructions:'服用資料核對後顯示',status:'unknown'}],source_file_ids:[],appointment:{date:offset(3),time:'09:30',location:'家庭診所（示範）',status:'scheduled'}},{id:'demo-2',patient_id:'grandma',date:offset(-12),doctor:'林醫生（示範）',clinic:'專科門診（示範）',diagnosis:'這裡會保留醫生的診斷與跟進內容。',status:'confirmed',notes:'所有示範內容只留在這次瀏覽。',medicines:[{id:'demo-m2',name:'示範藥品 B',strength:'按藥袋原文',dose:'待核對',frequency:'待核對',instructions:'',status:'unknown'}],source_file_ids:[],appointment:{date:offset(9),time:'14:15',location:'專科門診（示範）',status:'scheduled'}},{id:'demo-3',patient_id:'grandpa',date:offset(-20),doctor:'陳醫生（示範）',clinic:'家庭診所（示範）',diagnosis:'待核對的紀錄會有清楚標示。',review_notes:'示範：請核對相片內的日期及藥名。',status:'draft',medicines:[],source_file_ids:[]}],attachments:[],published_at:new Date().toISOString()};}
async function init(){
 const epoch=++initEpoch;
 try{
  state.shareAccess=!localHost&&new URLSearchParams(String(location.hash||'').replace(/^#/, '')).has('share');
  if(state.shareAccess){
   state.view='family';state.demo=false;state.client?.destroy();state.mode='share';
   state.client=createShareClient(cloudConfig,readShareToken(location.hash),{onDenied:()=>{if(epoch===initEpoch)clearSharedView();}});
   await loadData();if(epoch!==initEpoch)return;render();return;
  }
  if(state.demo){state.mode='local';state.data=sampleData();render();return;}
  if(localHost){state.mode='local';const boot=await api('/bootstrap');if(epoch!==initEpoch)return;state.boot=boot;await loadData();if(epoch!==initEpoch)return;render();return;}
  if(!cloudConfig.supabaseUrl||!cloudConfig.supabaseAnonKey){state.mode='setup';render();return;}
  state.client?.destroy();const client=createCloudClient(cloudConfig);state.client=client;
  client.onAuthChange(session=>{if(epoch!==initEpoch)return;state.session=session;if(!session)clearPrivateView();});
  const session=await client.getSession();if(epoch!==initEpoch)return;state.session=session;
  if(!session){state.mode='login';render();return;}
  state.mode='cloud';await loadData();if(epoch!==initEpoch)return;render();
 }catch(err){
  if(epoch!==initEpoch)return;
  state.error=err.message;
  if(state.shareAccess){state.data={patients:[],visits:[],reports:[],attachments:[]};state.mode='share-denied';}
  else state.mode=state.mode==='cloud'?'denied':state.mode==='loading'?'local':state.mode;
  render();
 }
}
window.addEventListener('hashchange',()=>{if(localHost)return;++initEpoch;++dataEpoch;++dialogEpoch;state.client?.destroy();clearUrls();redaction=null;$('#dialog')?.close();state.data={patients:[],visits:[],reports:[],attachments:[]};state.person=null;state.detail=null;state.editor=null;state.mode='loading';$('#app').innerHTML=`<main class="auth"><p>${t('loading')}</p></main>`;init();});
init();
